import { getAllProducts } from '@/lib/db';
import { unstable_cache, revalidateTag } from 'next/cache';

const getProducts = unstable_cache(
  async () => {
    return await getAllProducts();
  },
  ['products-list'],
  { tags: ['products'] }
);

export default async function Page() {
  const products = await getProducts();

  async function syncCatalog() {
    'use server';
    revalidateTag('products');
  }

  return (
    <div className="p-8">
      <h1 className="text-2xl font-bold mb-4">Product Catalog</h1>

      <div className="mb-6">
        <form action={syncCatalog}>
          <button 
            type="submit"
            className="bg-blue-500 text-white px-4 py-2 rounded hover:bg-blue-600"
          >
            Sync latest catalog
          </button>
        </form>
        <p className="text-sm text-gray-500 mt-2">
          Sync triggers a background refresh. Data may be briefly stale.
        </p>
      </div>

      <div className="grid gap-4">
        {products.map((product: any) => (
          <div key={product.id} className="border p-4 rounded shadow-sm">
            <div className="font-semibold">{product.name}</div>
            <div className="text-green-600">${product.price}</div>
          </div>
        ))}
      </div>

      <div className="mt-8 text-xs text-gray-400">
        Products loaded at {new Date().toLocaleTimeString()}
      </div>
    </div>
  );
}

import { getAllProducts } from '@/lib/db';
import { unstable_cache, revalidateTag } from 'next/cache';

type Product = {
  id: number;
  name: string;
  price: number;
};

const getProducts = unstable_cache(
  async () => {
    return await getAllProducts() as Product[];
  },
  ['products-list'],
  { tags: ['products'] }
);

export default async function Page() {
  const products = await getProducts();

  async function syncCatalog() {
    'use server';
    revalidateTag('products');
  }

  return (
    <div className="p-8 font-sans">
      <h1 className="text-2xl font-bold mb-6">Product Catalog</h1>

      <div className="mb-8 p-4 bg-gray-50 rounded-lg border">
        <h2 className="font-semibold mb-2">Actions</h2>
        <form action={syncCatalog} className="flex gap-4 items-center">
          <button 
            type="submit"
            className="px-4 py-2 bg-blue-600 text-white rounded hover:bg-blue-700 transition-colors"
          >
            Sync latest catalog
          </button>
          <p className="text-sm text-gray-600">
            Updates may take a moment to appear.
          </p>
        </form>
      </div>

      <div className="overflow-x-auto">
        <table className="min-w-full text-left border-collapse">
          <thead>
            <tr className="border-b bg-gray-100">
              <th className="p-4 font-semibold">ID</th>
              <th className="p-4 font-semibold">Product Name</th>
              <th className="p-4 font-semibold">Price</th>
            </tr>
          </thead>
          <tbody>
            {products.map((product) => (
              <tr key={product.id} className="border-b hover:bg-gray-50">
                <td className="p-4 text-gray-600">#{product.id}</td>
                <td className="p-4 font-medium">{product.name}</td>
                <td className="p-4 text-green-700 font-mono">
                  ${product.price.toFixed(2)}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      <footer className="mt-8 text-xs text-gray-400">
        Last rendered: {new Date().toLocaleTimeString()}
      </footer>
    </div>
  );
}

